from pathlib import Path

backend_path = Path("backend/promoter.js")
admin_path = Path("frontend/public/promoter-admin/index.html")

backend = backend_path.read_text(encoding="utf-8")
admin = admin_path.read_text(encoding="utf-8")

backend_routes = '\n  /*\n  =========================================================\n  LIVEBRIDGE PROMOTER ADMIN OVERSIGHT V1\n  ADMIN - PROMOTER FULL DETAIL\n  =========================================================\n  */\n\n  if(\n    request.method ===\n      "GET" &&\n    url.pathname ===\n      "/promoter-admin/promoter-detail"\n  ) {\n\n    const promoterId =\n      Number(\n        url.searchParams.get("id") ||\n        0\n      );\n\n    if(!promoterId) {\n      return j(\n        {\n          success:false,\n          error:"Promoter ID is required."\n        },\n        400\n      );\n    }\n\n    const promoter =\n      await env.TRANSLATIONS_DB\n        .prepare(`\n          SELECT *\n          FROM promoter_users\n          WHERE id = ?\n          LIMIT 1\n        `)\n        .bind(promoterId)\n        .first();\n\n    if(!promoter) {\n      return j(\n        {\n          success:false,\n          error:"Promoter not found."\n        },\n        404\n      );\n    }\n\n    const [\n      planResult,\n      leadResult,\n      offerResult,\n      commissionResult,\n      changeResult\n    ] = await Promise.all([\n      env.TRANSLATIONS_DB\n        .prepare(`\n          SELECT *\n          FROM promoter_plan_requests\n          WHERE promoter_id = ?\n          ORDER BY created_at DESC\n        `)\n        .bind(promoterId)\n        .all(),\n\n      env.TRANSLATIONS_DB\n        .prepare(`\n          SELECT *\n          FROM promoter_leads\n          WHERE promoter_id = ?\n          ORDER BY updated_at DESC\n        `)\n        .bind(promoterId)\n        .all(),\n\n      env.TRANSLATIONS_DB\n        .prepare(`\n          SELECT\n            pol.*,\n            o.recipient_name,\n            o.recipient_email,\n            o.expiration_timestamp,\n            o.max_redemptions,\n            o.redemption_count,\n            o.status,\n            o.note,\n            p.plan_name,\n            p.plan_code,\n            p.price_cents,\n            p.currency,\n            p.billing_interval\n          FROM promoter_offer_links pol\n          INNER JOIN offers o\n            ON o.token = pol.offer_token\n          INNER JOIN plans p\n            ON p.id = pol.plan_id\n          WHERE pol.promoter_id = ?\n          ORDER BY pol.created_at DESC\n        `)\n        .bind(promoterId)\n        .all(),\n\n      env.TRANSLATIONS_DB\n        .prepare(`\n          SELECT *\n          FROM promoter_commissions\n          WHERE promoter_id = ?\n          ORDER BY earned_at DESC\n        `)\n        .bind(promoterId)\n        .all(),\n\n      env.TRANSLATIONS_DB\n        .prepare(`\n          SELECT *\n          FROM promoter_change_requests\n          WHERE promoter_id = ?\n          ORDER BY created_at DESC\n        `)\n        .bind(promoterId)\n        .all()\n    ]);\n\n    let clients = [];\n\n    try {\n      const clientResult =\n        await env.TRANSLATIONS_DB\n          .prepare(`\n            SELECT\n              pc.*,\n              o.organization_name,\n              o.account_holder,\n              o.email,\n              o.account_email,\n              o.phone,\n              o.room_name,\n              o.plan_code,\n              o.plan_name,\n              o.account_status,\n              o.billing_status\n            FROM promoter_clients pc\n            LEFT JOIN organizations o\n              ON o.id = pc.organization_id\n            WHERE pc.promoter_id = ?\n            ORDER BY pc.landed_at DESC\n          `)\n          .bind(promoterId)\n          .all();\n\n      clients =\n        clientResult.results ||\n        [];\n\n    } catch {\n      const clientResult =\n        await env.TRANSLATIONS_DB\n          .prepare(`\n            SELECT *\n            FROM promoter_clients\n            WHERE promoter_id = ?\n            ORDER BY landed_at DESC\n          `)\n          .bind(promoterId)\n          .all();\n\n      clients =\n        clientResult.results ||\n        [];\n    }\n\n    return j({\n      success:true,\n      promoter:promoterJson(promoter),\n      plans:(planResult.results || []).map(planJson),\n      leads:leadResult.results || [],\n      clients,\n      offers:offerResult.results || [],\n      commissions:commissionResult.results || [],\n      changeRequests:changeResult.results || []\n    });\n  }\n\n\n  /*\n  =========================================================\n  LIVEBRIDGE PROMOTER ADMIN OVERSIGHT V1\n  ADMIN - UPDATE PROMOTER\n  =========================================================\n  */\n\n  if(\n    request.method ===\n      "POST" &&\n    url.pathname ===\n      "/promoter-admin/promoter-update"\n  ) {\n\n    const body =\n      await request.json();\n\n    const promoterId =\n      Number(body.id || 0);\n\n    const displayName =\n      text(body.displayName, 200);\n\n    if(\n      !promoterId ||\n      !displayName\n    ) {\n      return j(\n        {\n          success:false,\n          error:"Promoter ID and name are required."\n        },\n        400\n      );\n    }\n\n    const exists =\n      await env.TRANSLATIONS_DB\n        .prepare(`\n          SELECT id\n          FROM promoter_users\n          WHERE id = ?\n          LIMIT 1\n        `)\n        .bind(promoterId)\n        .first();\n\n    if(!exists) {\n      return j(\n        {\n          success:false,\n          error:"Promoter not found."\n        },\n        404\n      );\n    }\n\n    const monthly =\n      Math.max(\n        0,\n        Math.min(\n          100,\n          Number(\n            body.monthlyCommissionPercent ||\n            0\n          )\n        )\n      );\n\n    const annual =\n      Math.max(\n        0,\n        Math.min(\n          100,\n          Number(\n            body.annualCommissionPercent ||\n            0\n          )\n        )\n      );\n\n    const holdDays =\n      Math.max(\n        0,\n        Math.min(\n          365,\n          Math.round(\n            Number(\n              body.commissionHoldDays ||\n              0\n            )\n          )\n        )\n      );\n\n    const active =\n      body.active === false ||\n      body.active === 0\n        ? 0\n        : 1;\n\n    await env.TRANSLATIONS_DB\n      .prepare(`\n        UPDATE promoter_users\n        SET\n          display_name = ?,\n          email = ?,\n          phone = ?,\n          monthly_commission_percent = ?,\n          annual_commission_percent = ?,\n          commission_hold_days = ?,\n          notes = ?,\n          active = ?,\n          updated_at = ?\n        WHERE id = ?\n      `)\n      .bind(\n        displayName,\n        text(body.email, 250),\n        text(body.phone, 100),\n        monthly,\n        annual,\n        holdDays,\n        text(body.notes, 2000),\n        active,\n        Date.now(),\n        promoterId\n      )\n      .run();\n\n    const updated =\n      await env.TRANSLATIONS_DB\n        .prepare(`\n          SELECT *\n          FROM promoter_users\n          WHERE id = ?\n          LIMIT 1\n        `)\n        .bind(promoterId)\n        .first();\n\n    return j({\n      success:true,\n      promoter:promoterJson(updated)\n    });\n  }\n\n\n  /*\n  =========================================================\n  LIVEBRIDGE PROMOTER ADMIN OVERSIGHT V1\n  ADMIN - PERMANENT DELETE PROMOTER\n  =========================================================\n  */\n\n  if(\n    request.method ===\n      "POST" &&\n    url.pathname ===\n      "/promoter-admin/promoter-delete"\n  ) {\n\n    const body =\n      await request.json();\n\n    const promoterId =\n      Number(body.id || 0);\n\n    if(!promoterId) {\n      return j(\n        {\n          success:false,\n          error:"Promoter ID is required."\n        },\n        400\n      );\n    }\n\n    const promoter =\n      await env.TRANSLATIONS_DB\n        .prepare(`\n          SELECT id, display_name\n          FROM promoter_users\n          WHERE id = ?\n          LIMIT 1\n        `)\n        .bind(promoterId)\n        .first();\n\n    if(!promoter) {\n      return j(\n        {\n          success:false,\n          error:"Promoter not found."\n        },\n        404\n      );\n    }\n\n    const dependency =\n      await env.TRANSLATIONS_DB\n        .prepare(`\n          SELECT\n            (\n              SELECT COUNT(*)\n              FROM promoter_clients\n              WHERE promoter_id = ?\n            ) AS client_count,\n            (\n              SELECT COUNT(*)\n              FROM promoter_commissions\n              WHERE promoter_id = ?\n            ) AS commission_count,\n            (\n              SELECT COUNT(*)\n              FROM promoter_offer_links\n              WHERE promoter_id = ?\n            ) AS offer_count\n        `)\n        .bind(\n          promoterId,\n          promoterId,\n          promoterId\n        )\n        .first();\n\n    const clientCount =\n      Number(\n        dependency?.client_count ||\n        0\n      );\n\n    const commissionCount =\n      Number(\n        dependency?.commission_count ||\n        0\n      );\n\n    const offerCount =\n      Number(\n        dependency?.offer_count ||\n        0\n      );\n\n    if(\n      clientCount ||\n      commissionCount ||\n      offerCount\n    ) {\n      return j(\n        {\n          success:false,\n          error:\n            "This promoter has client, commission, or offer history. Disable the employee instead so business records are preserved."\n        },\n        409\n      );\n    }\n\n    await env.TRANSLATIONS_DB\n      .batch([\n        env.TRANSLATIONS_DB\n          .prepare(`\n            DELETE FROM promoter_change_requests\n            WHERE promoter_id = ?\n          `)\n          .bind(promoterId),\n\n        env.TRANSLATIONS_DB\n          .prepare(`\n            DELETE FROM promoter_leads\n            WHERE promoter_id = ?\n          `)\n          .bind(promoterId),\n\n        env.TRANSLATIONS_DB\n          .prepare(`\n            DELETE FROM promoter_plan_requests\n            WHERE promoter_id = ?\n          `)\n          .bind(promoterId),\n\n        env.TRANSLATIONS_DB\n          .prepare(`\n            DELETE FROM promoter_users\n            WHERE id = ?\n          `)\n          .bind(promoterId)\n      ]);\n\n    return j({\n      success:true\n    });\n  }\n\n\n'
css = '\n/* LIVEBRIDGE PROMOTER ADMIN OVERSIGHT V1 */\n\n.promoter-clickable{\n  cursor:pointer;\n  border-radius:12px;\n  padding-left:12px;\n  padding-right:12px;\n  transition:\n    background .15s ease,\n    transform .15s ease;\n}\n\n.promoter-clickable:hover{\n  background:rgba(45,151,255,.08);\n  transform:translateY(-1px);\n}\n\n.promoter-detail-card{\n  border-color:rgba(45,151,255,.28);\n}\n\n.detail-top{\n  display:flex;\n  align-items:flex-start;\n  justify-content:space-between;\n  gap:14px;\n  margin-bottom:18px;\n}\n\n.detail-summary{\n  display:grid;\n  grid-template-columns:repeat(4,1fr);\n  gap:10px;\n  margin:16px 0 20px;\n}\n\n.detail-section{\n  margin-top:18px;\n  padding-top:18px;\n  border-top:1px solid rgba(255,255,255,.08);\n}\n\n.detail-section-title{\n  font-size:15px;\n  font-weight:900;\n  margin-bottom:10px;\n}\n\n.detail-data-row{\n  padding:12px 0;\n  border-bottom:1px solid rgba(255,255,255,.07);\n}\n\n.detail-data-row:last-child{\n  border-bottom:none;\n}\n\n.detail-row-head{\n  display:flex;\n  justify-content:space-between;\n  gap:12px;\n  align-items:flex-start;\n  margin-bottom:4px;\n}\n\n.detail-note{\n  margin-top:7px;\n  padding:8px 10px;\n  border-radius:9px;\n  background:rgba(255,255,255,.035);\n  color:#b8cadc;\n  font-size:11px;\n  line-height:1.5;\n}\n\n.detail-actions{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:10px;\n  flex-wrap:wrap;\n  margin-top:16px;\n}\n\n.detail-danger-actions{\n  display:flex;\n  gap:8px;\n  flex-wrap:wrap;\n}\n\n@media(max-width:760px){\n  .detail-summary{\n    grid-template-columns:1fr 1fr;\n  }\n\n  .detail-top{\n    flex-direction:column;\n  }\n}\n\n'
detail_html = '\n    <!-- LIVEBRIDGE PROMOTER ADMIN OVERSIGHT V1 -->\n\n    <div\n      class="card promoter-detail-card"\n      id="promoterDetailCard"\n      style="display:none;"\n    >\n\n      <div class="detail-top">\n\n        <div>\n          <button\n            class="secondary"\n            id="closePromoterDetailButton"\n            type="button"\n          >\n            ← Back to Promoters\n          </button>\n\n          <div\n            class="title"\n            id="detailPromoterTitle"\n            style="margin-top:14px;"\n          >\n            Employee / Promoter\n          </div>\n\n          <div\n            class="muted"\n            id="detailPromoterCode"\n          ></div>\n        </div>\n\n        <div id="detailStatusBadge"></div>\n\n      </div>\n\n\n      <div class="detail-summary">\n\n        <div class="stat">\n          <div class="muted">Portal Access</div>\n          <strong id="detailInviteStatus">—</strong>\n        </div>\n\n        <div class="stat">\n          <div class="muted">Plans</div>\n          <strong id="detailPlanCount">0</strong>\n        </div>\n\n        <div class="stat">\n          <div class="muted">Clients</div>\n          <strong id="detailClientCount">0</strong>\n        </div>\n\n        <div class="stat">\n          <div class="muted">Commission Owed</div>\n          <strong id="detailCommissionTotal">$0.00</strong>\n        </div>\n\n      </div>\n\n\n      <div class="grid">\n\n        <div class="field">\n          <label>Name</label>\n          <input id="detailName">\n        </div>\n\n        <div class="field">\n          <label>Contact Email</label>\n          <input id="detailEmail" type="email">\n        </div>\n\n        <div class="field">\n          <label>Phone</label>\n          <input id="detailPhone">\n        </div>\n\n        <div class="field">\n          <label>Promoter Code</label>\n          <input id="detailCode" readonly>\n        </div>\n\n        <div class="field">\n          <label>Monthly Commission %</label>\n          <input\n            id="detailMonthlyCommission"\n            type="number"\n            min="0"\n            max="100"\n            step=".1"\n          >\n        </div>\n\n        <div class="field">\n          <label>Annual Commission %</label>\n          <input\n            id="detailAnnualCommission"\n            type="number"\n            min="0"\n            max="100"\n            step=".1"\n          >\n        </div>\n\n        <div class="field">\n          <label>Commission Hold Days</label>\n          <input\n            id="detailHoldDays"\n            type="number"\n            min="0"\n            max="365"\n            step="1"\n          >\n        </div>\n\n        <div class="field full">\n          <label>Private Admin Notes</label>\n          <textarea id="detailNotes"></textarea>\n        </div>\n\n      </div>\n\n\n      <div class="detail-actions">\n\n        <div class="detail-danger-actions">\n\n          <button\n            class="red"\n            id="deletePromoterButton"\n            type="button"\n          >\n            Permanent Delete\n          </button>\n\n          <button\n            class="secondary"\n            id="togglePromoterButton"\n            type="button"\n          >\n            Disable Employee\n          </button>\n\n        </div>\n\n        <button\n          class="green"\n          id="savePromoterButton"\n          type="button"\n        >\n          Save Changes\n        </button>\n\n      </div>\n\n      <div id="detailMessage" class="message"></div>\n\n\n      <div class="detail-section">\n        <div class="detail-section-title">Plans</div>\n        <div id="detailPlans"></div>\n      </div>\n\n      <div class="detail-section">\n        <div class="detail-section-title">Leads</div>\n        <div id="detailLeads"></div>\n      </div>\n\n      <div class="detail-section">\n        <div class="detail-section-title">Clients</div>\n        <div id="detailClients"></div>\n      </div>\n\n      <div class="detail-section">\n        <div class="detail-section-title">Offers</div>\n        <div id="detailOffers"></div>\n      </div>\n\n      <div class="detail-section">\n        <div class="detail-section-title">Commissions</div>\n        <div id="detailCommissions"></div>\n      </div>\n\n      <div class="detail-section">\n        <div class="detail-section-title">Client Change Requests</div>\n        <div id="detailChangeRequests"></div>\n      </div>\n\n    </div>\n\n\n'
js = '\n// LIVEBRIDGE PROMOTER ADMIN OVERSIGHT V1\n\nlet currentPromoterDetail = null;\n\n\nfunction detailEmpty(value){\n  return `\n    <div class="empty">\n      ${escapeHtml(value)}\n    </div>\n  `;\n}\n\n\nfunction formatDate(value){\n  const n = Number(value || 0);\n  if(!n) return "—";\n  try{\n    return new Date(n).toLocaleString("en-CA");\n  }catch{\n    return "—";\n  }\n}\n\n\nfunction statusBadge(value){\n  const status =\n    String(value || "")\n      .trim()\n      .toLowerCase();\n\n  const badgeClass =\n    status === "approved" ||\n    status === "active" ||\n    status === "paid" ||\n    status === "payable"\n      ? "approved"\n      : status === "pending" ||\n        status === "trialing"\n        ? "pending"\n        : status === "rejected" ||\n          status === "disabled" ||\n          status === "canceled" ||\n          status === "cancelled" ||\n          status === "failed"\n          ? "rejected"\n          : "";\n\n  return `\n    <span class="badge ${badgeClass}">\n      ${escapeHtml(status || "unknown")}\n    </span>\n  `;\n}\n\n\nfunction renderPromoterDetail(data){\n\n  currentPromoterDetail = data;\n\n  const promoter =\n    data.promoter || {};\n\n  document.getElementById(\n    "detailPromoterTitle"\n  ).textContent =\n    promoter.displayName ||\n    "Employee / Promoter";\n\n  document.getElementById(\n    "detailPromoterCode"\n  ).textContent =\n    promoter.promoterCode\n      ? "Promoter Code: " +\n        promoter.promoterCode\n      : "";\n\n  document.getElementById(\n    "detailStatusBadge"\n  ).innerHTML =\n    statusBadge(\n      promoter.active\n        ? "active"\n        : "disabled"\n    );\n\n  document.getElementById(\n    "detailInviteStatus"\n  ).textContent =\n    promoter.inviteClaimed\n      ? "Connected"\n      : "Invite Pending";\n\n  document.getElementById(\n    "detailPlanCount"\n  ).textContent =\n    Number(\n      data.plans?.length || 0\n    );\n\n  document.getElementById(\n    "detailClientCount"\n  ).textContent =\n    Number(\n      data.clients?.length || 0\n    );\n\n  const commissionTotal =\n    (data.commissions || [])\n      .filter(\n        item =>\n          String(item.status || "")\n            .toLowerCase() !==\n          "paid"\n      )\n      .reduce(\n        (total,item) =>\n          total +\n          Number(\n            item.commission_cents || 0\n          ),\n        0\n      );\n\n  document.getElementById(\n    "detailCommissionTotal"\n  ).textContent =\n    money(commissionTotal);\n\n  document.getElementById(\n    "detailName"\n  ).value =\n    promoter.displayName || "";\n\n  document.getElementById(\n    "detailEmail"\n  ).value =\n    promoter.email || "";\n\n  document.getElementById(\n    "detailPhone"\n  ).value =\n    promoter.phone || "";\n\n  document.getElementById(\n    "detailCode"\n  ).value =\n    promoter.promoterCode || "";\n\n  document.getElementById(\n    "detailMonthlyCommission"\n  ).value =\n    Number(\n      promoter.monthlyCommissionPercent || 0\n    );\n\n  document.getElementById(\n    "detailAnnualCommission"\n  ).value =\n    Number(\n      promoter.annualCommissionPercent || 0\n    );\n\n  document.getElementById(\n    "detailHoldDays"\n  ).value =\n    Number(\n      promoter.commissionHoldDays || 0\n    );\n\n  document.getElementById(\n    "detailNotes"\n  ).value =\n    promoter.notes || "";\n\n  document.getElementById(\n    "togglePromoterButton"\n  ).textContent =\n    promoter.active\n      ? "Disable Employee"\n      : "Enable Employee";\n\n\n  const plans =\n    data.plans || [];\n\n  document.getElementById(\n    "detailPlans"\n  ).innerHTML =\n    plans.length\n      ? plans.map(\n          plan => {\n            const hours =\n              Math.round(\n                Number(\n                  plan.includedMinutes || 0\n                ) /\n                60 *\n                10\n              ) /\n              10;\n\n            return `\n              <div class="detail-data-row">\n                <div class="detail-row-head">\n                  <strong>\n                    ${escapeHtml(\n                      plan.planName ||\n                      "Unnamed Plan"\n                    )}\n                  </strong>\n                  ${statusBadge(plan.status)}\n                </div>\n\n                <div class="muted">\n                  ${escapeHtml(\n                    plan.planCode || ""\n                  )}\n                  ·\n                  ${money(\n                    plan.priceCents,\n                    plan.currency\n                  )}\n                  /\n                  ${escapeHtml(\n                    plan.billingInterval ||\n                    "month"\n                  )}\n                  ·\n                  ${hours} hours\n                  ·\n                  ${Number(\n                    plan.viewerLimit || 0\n                  )} viewers\n                </div>\n\n                ${\n                  plan.description\n                    ? `\n                      <div class="detail-note">\n                        ${escapeHtml(\n                          plan.description\n                        )}\n                      </div>\n                    `\n                    : ""\n                }\n\n                ${\n                  plan.note\n                    ? `\n                      <div class="detail-note">\n                        <strong>Promoter note:</strong>\n                        ${escapeHtml(plan.note)}\n                      </div>\n                    `\n                    : ""\n                }\n\n                ${\n                  plan.adminFeedback\n                    ? `\n                      <div class="detail-note">\n                        <strong>Admin feedback:</strong>\n                        ${escapeHtml(\n                          plan.adminFeedback\n                        )}\n                      </div>\n                    `\n                    : ""\n                }\n              </div>\n            `;\n          }\n        ).join("")\n      : detailEmpty(\n          "No plans saved."\n        );\n\n\n  const leads =\n    data.leads || [];\n\n  document.getElementById(\n    "detailLeads"\n  ).innerHTML =\n    leads.length\n      ? leads.map(\n          lead => `\n            <div class="detail-data-row">\n              <div class="detail-row-head">\n                <strong>\n                  ${escapeHtml(\n                    lead.organization_name ||\n                    "Unnamed Lead"\n                  )}\n                </strong>\n                ${statusBadge(lead.status)}\n              </div>\n\n              <div class="muted">\n                ${escapeHtml(\n                  lead.contact_name || ""\n                )}\n                ${\n                  lead.email\n                    ? " · " +\n                      escapeHtml(lead.email)\n                    : ""\n                }\n                ${\n                  lead.phone\n                    ? " · " +\n                      escapeHtml(lead.phone)\n                    : ""\n                }\n              </div>\n\n              ${\n                lead.notes\n                  ? `\n                    <div class="detail-note">\n                      ${escapeHtml(lead.notes)}\n                    </div>\n                  `\n                  : ""\n              }\n            </div>\n          `\n        ).join("")\n      : detailEmpty(\n          "No leads saved."\n        );\n\n\n  const clients =\n    data.clients || [];\n\n  document.getElementById(\n    "detailClients"\n  ).innerHTML =\n    clients.length\n      ? clients.map(\n          client => `\n            <div class="detail-data-row">\n              <div class="detail-row-head">\n                <strong>\n                  ${escapeHtml(\n                    client.organization_name ||\n                    (\n                      "Organization #" +\n                      Number(\n                        client.organization_id || 0\n                      )\n                    )\n                  )}\n                </strong>\n\n                ${statusBadge(\n                  client.active === 0\n                    ? "disabled"\n                    : (\n                        client.billing_status ||\n                        client.account_status ||\n                        "active"\n                      )\n                )}\n              </div>\n\n              <div class="muted">\n                ${escapeHtml(\n                  client.account_holder || ""\n                )}\n                ${\n                  (\n                    client.account_email ||\n                    client.email\n                  )\n                    ? " · " +\n                      escapeHtml(\n                        client.account_email ||\n                        client.email\n                      )\n                    : ""\n                }\n                ${\n                  client.phone\n                    ? " · " +\n                      escapeHtml(client.phone)\n                    : ""\n                }\n              </div>\n\n              <div class="detail-note">\n                Plan:\n                <strong>\n                  ${escapeHtml(\n                    client.plan_name ||\n                    client.plan_code ||\n                    "—"\n                  )}\n                </strong>\n                ${\n                  client.room_name\n                    ? " · Room: " +\n                      escapeHtml(\n                        client.room_name\n                      )\n                    : ""\n                }\n              </div>\n            </div>\n          `\n        ).join("")\n      : detailEmpty(\n          "No clients attributed yet."\n        );\n\n\n  const offers =\n    data.offers || [];\n\n  document.getElementById(\n    "detailOffers"\n  ).innerHTML =\n    offers.length\n      ? offers.map(\n          offer => `\n            <div class="detail-data-row">\n              <div class="detail-row-head">\n                <strong>\n                  ${escapeHtml(\n                    offer.plan_name ||\n                    offer.plan_code ||\n                    "Offer"\n                  )}\n                </strong>\n                ${statusBadge(offer.status)}\n              </div>\n\n              <div class="muted">\n                ${escapeHtml(\n                  offer.recipient_name ||\n                  "Open recipient"\n                )}\n                ${\n                  offer.recipient_email\n                    ? " · " +\n                      escapeHtml(\n                        offer.recipient_email\n                      )\n                    : ""\n                }\n                ·\n                ${Number(\n                  offer.redemption_count || 0\n                )}\n                /\n                ${Number(\n                  offer.max_redemptions || 0\n                )}\n                redeemed\n              </div>\n\n              ${\n                offer.note\n                  ? `\n                    <div class="detail-note">\n                      ${escapeHtml(offer.note)}\n                    </div>\n                  `\n                  : ""\n              }\n            </div>\n          `\n        ).join("")\n      : detailEmpty(\n          "No offers created."\n        );\n\n\n  const commissions =\n    data.commissions || [];\n\n  document.getElementById(\n    "detailCommissions"\n  ).innerHTML =\n    commissions.length\n      ? commissions.map(\n          item => `\n            <div class="detail-data-row">\n              <div class="detail-row-head">\n                <strong>\n                  ${money(\n                    item.commission_cents\n                  )}\n                </strong>\n                ${statusBadge(item.status)}\n              </div>\n\n              <div class="muted">\n                ${Number(\n                  item.commission_percent || 0\n                )}% commission\n                · Sale:\n                ${money(\n                  item.sale_amount_cents\n                )}\n                · Plan:\n                ${escapeHtml(\n                  item.plan_code || "—"\n                )}\n              </div>\n\n              <div class="detail-note">\n                Earned:\n                ${escapeHtml(\n                  formatDate(item.earned_at)\n                )}\n                · Payable:\n                ${escapeHtml(\n                  formatDate(item.payable_at)\n                )}\n              </div>\n\n              ${\n                item.notes\n                  ? `\n                    <div class="detail-note">\n                      ${escapeHtml(item.notes)}\n                    </div>\n                  `\n                  : ""\n              }\n            </div>\n          `\n        ).join("")\n      : detailEmpty(\n          "No commission records."\n        );\n\n\n  const requests =\n    data.changeRequests || [];\n\n  document.getElementById(\n    "detailChangeRequests"\n  ).innerHTML =\n    requests.length\n      ? requests.map(\n          request => `\n            <div class="detail-data-row">\n              <div class="detail-row-head">\n                <strong>\n                  ${escapeHtml(\n                    request.request_type ||\n                    "Client Request"\n                  )}\n                </strong>\n                ${statusBadge(request.status)}\n              </div>\n\n              <div class="muted">\n                Organization #\n                ${Number(\n                  request.organization_id || 0\n                )}\n                ·\n                ${escapeHtml(\n                  formatDate(\n                    request.created_at\n                  )\n                )}\n              </div>\n\n              <div class="detail-note">\n                ${escapeHtml(\n                  request.details || ""\n                )}\n              </div>\n\n              ${\n                request.admin_response\n                  ? `\n                    <div class="detail-note">\n                      <strong>Admin response:</strong>\n                      ${escapeHtml(\n                        request.admin_response\n                      )}\n                    </div>\n                  `\n                  : ""\n              }\n            </div>\n          `\n        ).join("")\n      : detailEmpty(\n          "No client change requests."\n        );\n}\n\n\nasync function openPromoter(promoterId){\n\n  const card =\n    document.getElementById(\n      "promoterDetailCard"\n    );\n\n  card.style.display =\n    "block";\n\n  document.getElementById(\n    "detailPromoterTitle"\n  ).textContent =\n    "Loading employee...";\n\n  document.getElementById(\n    "detailMessage"\n  ).className =\n    "message";\n\n  card.scrollIntoView({\n    behavior:"smooth",\n    block:"start"\n  });\n\n  try{\n\n    const response =\n      await api(\n        "/promoter-admin/promoter-detail?id=" +\n        encodeURIComponent(promoterId)\n      );\n\n    const data =\n      await response.json();\n\n    if(!response.ok){\n      throw new Error(\n        data.error ||\n        "Unable to load promoter."\n      );\n    }\n\n    renderPromoterDetail(data);\n\n  }catch(error){\n\n    const message =\n      document.getElementById(\n        "detailMessage"\n      );\n\n    message.textContent =\n      error.message ||\n      "Unable to load promoter.";\n\n    message.className =\n      "message bad";\n  }\n}\n\n\nfunction closePromoterDetail(){\n\n  document.getElementById(\n    "promoterDetailCard"\n  ).style.display =\n    "none";\n\n  currentPromoterDetail =\n    null;\n}\n\n\nasync function savePromoterProfile(\n  activeOverride=null\n){\n\n  if(\n    !currentPromoterDetail\n      ?.promoter\n      ?.id\n  ){\n    return;\n  }\n\n  const message =\n    document.getElementById(\n      "detailMessage"\n    );\n\n  message.className =\n    "message";\n\n  const active =\n    activeOverride === null\n      ? !!currentPromoterDetail\n          .promoter\n          .active\n      : !!activeOverride;\n\n  try{\n\n    const response =\n      await api(\n        "/promoter-admin/promoter-update",\n        {\n          method:"POST",\n          body:JSON.stringify({\n            id:\n              Number(\n                currentPromoterDetail\n                  .promoter\n                  .id\n              ),\n\n            displayName:\n              document.getElementById(\n                "detailName"\n              ).value.trim(),\n\n            email:\n              document.getElementById(\n                "detailEmail"\n              ).value.trim(),\n\n            phone:\n              document.getElementById(\n                "detailPhone"\n              ).value.trim(),\n\n            monthlyCommissionPercent:\n              Number(\n                document.getElementById(\n                  "detailMonthlyCommission"\n                ).value || 0\n              ),\n\n            annualCommissionPercent:\n              Number(\n                document.getElementById(\n                  "detailAnnualCommission"\n                ).value || 0\n              ),\n\n            commissionHoldDays:\n              Number(\n                document.getElementById(\n                  "detailHoldDays"\n                ).value || 0\n              ),\n\n            notes:\n              document.getElementById(\n                "detailNotes"\n              ).value.trim(),\n\n            active\n          })\n        }\n      );\n\n    const data =\n      await response.json();\n\n    if(!response.ok){\n      throw new Error(\n        data.error ||\n        "Unable to save promoter."\n      );\n    }\n\n    message.textContent =\n      "✓ Employee details saved.";\n\n    message.className =\n      "message good";\n\n    await Promise.all([\n      loadPromoters(),\n      loadPlanRequests()\n    ]);\n\n    await openPromoter(\n      data.promoter.id\n    );\n\n  }catch(error){\n\n    message.textContent =\n      error.message ||\n      "Unable to save promoter.";\n\n    message.className =\n      "message bad";\n  }\n}\n\n\nasync function togglePromoterAccess(){\n\n  if(\n    !currentPromoterDetail\n      ?.promoter\n  ){\n    return;\n  }\n\n  const promoter =\n    currentPromoterDetail.promoter;\n\n  const nextActive =\n    !promoter.active;\n\n  const label =\n    nextActive\n      ? "enable"\n      : "disable";\n\n  if(\n    !confirm(\n      "Are you sure you want to " +\n      label +\n      " " +\n      (\n        promoter.displayName ||\n        "this employee"\n      ) +\n      "?"\n    )\n  ){\n    return;\n  }\n\n  await savePromoterProfile(\n    nextActive\n  );\n}\n\n\nasync function deletePromoterPermanently(){\n\n  if(\n    !currentPromoterDetail\n      ?.promoter\n      ?.id\n  ){\n    return;\n  }\n\n  const promoter =\n    currentPromoterDetail.promoter;\n\n  const typed =\n    prompt(\n      "Permanent delete removes this employee profile and unused test data. " +\n      "If business history exists, LiveBridge will block deletion. " +\n      "Type DELETE to permanently delete " +\n      (\n        promoter.displayName ||\n        "this employee"\n      ) +\n      "."\n    );\n\n  if(typed !== "DELETE"){\n    return;\n  }\n\n  const message =\n    document.getElementById(\n      "detailMessage"\n    );\n\n  try{\n\n    const response =\n      await api(\n        "/promoter-admin/promoter-delete",\n        {\n          method:"POST",\n          body:JSON.stringify({\n            id:Number(promoter.id)\n          })\n        }\n      );\n\n    const data =\n      await response.json();\n\n    if(!response.ok){\n      throw new Error(\n        data.error ||\n        "Unable to delete promoter."\n      );\n    }\n\n    closePromoterDetail();\n\n    await Promise.all([\n      loadPromoters(),\n      loadPlanRequests()\n    ]);\n\n    alert(\n      "Employee / promoter permanently deleted."\n    );\n\n  }catch(error){\n\n    message.textContent =\n      error.message ||\n      "Unable to delete promoter.";\n\n    message.className =\n      "message bad";\n  }\n}\n\n\n'

